/* 1) 基本 — 拿 dataURL */
const url = await ssp.viewerTool.screenshot();
console.log('screenshot length:', url.length); // ~几十 KB ~ 几 MB

/* 2) 触发下载 */
await ssp.viewerTool.screenshot({ download: true });
// 默认文件名 ssp-screenshot-<时间戳>.png, 自动下载到 ~/Downloads

/* 3) JPEG 高压缩 */
await ssp.viewerTool.screenshot({
  format: 'jpeg',
  quality: 0.7,
  download: true,
  filename: 'my-build.jpg',
});

/* 4) 自定义尺寸 (缩略图) */
await ssp.viewerTool.screenshot({ width: 320, height: 240, download: true });

/* 5) 配合 setViewpoint 拍固定视角 */
ssp.cameraController.setViewpoint({
  position: { x: 100, y: 50, z: 100 },
  target: { x: 0, y: 0, z: 0 },
});
await new Promise(r => setTimeout(r, 100)); // 等 transition 完成
await ssp.viewerTool.screenshot({ download: true, filename: 'fixed-view.png' });
